  @Test
  void shouldCreateLinkWithGeneratedCodeAndRedirectWith302() throws Exception {
    MvcResult created = postLink("{\"url\": \"" + TARGET + "\"}")
        .andExpect(status().isCreated())
        .andExpect(jsonPath("$.code").value(matchesPattern("^[0-9A-Za-z]{7}$")))
